/* Local activity editor. Public/shared content remains maintained in GitHub. */
function validateActivities(items){
 if(!Array.isArray(items)||items.length>50)throw Error('Máximo 50 actividades');
 return items.map((a,i)=>{if(!a||typeof a.title!=='string'||typeof a.question!=='string'||!Array.isArray(a.options)||a.options.length<2||a.options.length>4||!a.options.every(o=>typeof o==='string'&&o.trim())||!Number.isInteger(a.answer)||a.answer<0||a.answer>=a.options.length)throw Error('Actividad inválida');
 return {id:typeof a.id==='string'?a.id.slice(0,80):'import-'+i,title:a.title.trim().slice(0,80),question:a.question.trim().slice(0,250),symbol:typeof a.symbol==='string'?a.symbol.slice(0,20):'🌱',options:a.options.map(o=>o.trim().slice(0,120)),answer:a.answer,enabled:a.enabled!==false};});
}
try{state.activities=validateActivities(state.activities||[])}catch{state.activities=[]}
const originalHome=home;home=function(){originalHome();const available=state.activities.filter(a=>a.enabled);if(available.length){const section=document.createElement('section');section.className='panel';section.innerHTML='<h2>Mis actividades</h2><div class="grid">'+available.map((a,i)=>'<button class="card" data-custom-activity="'+i+'"><span class="emoji">'+escape(a.symbol)+'</span><strong>'+escape(a.title)+'</strong><small>Una actividad preparada para ti.</small></button>').join('')+'</div>';app.appendChild(section);section.querySelectorAll('[data-custom-activity]').forEach(b=>b.onclick=()=>playActivity(available[+b.dataset.customActivity].id));}}
function playActivity(id){const a=state.activities.find(a=>a.id===id);if(!a){home();return}render(title(escape(a.title),'Puedes escuchar, elegir y parar cuando quieras.')+'<section class="panel"><div class="big">'+escape(a.symbol)+'</div><h2>'+escape(a.question)+'</h2><button id="readActivity" class="secondary">🔊 Escuchar</button><div class="grid">'+a.options.map((o,i)=>'<button data-option="'+i+'">'+escape(o)+'</button>').join('')+'</div><div id="activityFeedback" class="feedback" aria-live="polite"></div><button id="activityFinish" class="hidden">Terminar →</button></section>');$('readActivity').onclick=()=>say(a.question);document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{if(+b.dataset.option===a.answer){$('activityFeedback').textContent='¡Lo encontraste!';say('Lo encontraste');document.querySelectorAll('[data-option]').forEach(x=>x.disabled=true);$('activityFinish').classList.remove('hidden')}else{$('activityFeedback').textContent='Podemos mirar de nuevo. Prueba otra opción.';say('Podemos mirar de nuevo')}});$('activityFinish').onclick=()=>finish('customActivities')}
function activityEditor(editId){const a=state.activities.find(x=>x.id===editId)||{title:'',question:'',symbol:'🌱',options:['',''],answer:0,enabled:true};render(title('Crear actividades','Preguntas de selección con 2 a 4 opciones. Se guardan en este dispositivo.')+'<div class="panel"><label for="aTitle">Nombre de la actividad</label><input id="aTitle" maxlength="80" value="'+escape(a.title)+'"><label for="aSymbol">Emoji o símbolo</label><input id="aSymbol" maxlength="20" value="'+escape(a.symbol)+'"><label for="aQuestion">Pregunta o instrucción</label><input id="aQuestion" maxlength="250" value="'+escape(a.question)+'"><label for="aOptions">Opciones (una por línea, mínimo 2 y máximo 4)</label><textarea id="aOptions" rows="4" style="width:100%;padding:13px;font:inherit">'+escape(a.options.join('\n'))+'</textarea><label for="aAnswer">Número de la opción correcta</label><select id="aAnswer">'+[0,1,2,3].map(i=>'<option value="'+i+'">'+(i+1)+'</option>').join('')+'</select><label><input id="aEnabled" type="checkbox" style="width:auto" '+(a.enabled?'checked':'')+'> Visible en el inicio</label><div class="bar"><button id="aSave">'+(editId?'Guardar cambios':'Agregar actividad')+'</button><button class="secondary" onclick="activityEditor()">Nuevo formulario</button><button class="secondary" onclick="family()">Volver a Familia</button></div><p id="aStatus" aria-live="polite"></p></div><section class="panel"><h2>Actividades creadas ('+state.activities.length+')</h2>'+state.activities.map((x,i)=>'<div class="row"><span>'+escape(x.symbol)+' '+escape(x.title)+(x.enabled?'':' · Oculta')+'</span><button class="secondary" data-edit="'+i+'">Editar</button><button class="secondary" data-delete="'+i+'">Eliminar</button></div>').join('')+'<p class="hint">Editar la app en GitHub permite compartir contenidos con todos. Este editor crea actividades locales; usa el respaldo de Familia para transferirlas.</p></section>');$('aAnswer').value=String(a.answer);$('aSave').onclick=()=>{try{const draft={id:editId||('activity-'+Date.now()+'-'+Math.random().toString(16).slice(2)),title:$('aTitle').value,question:$('aQuestion').value,symbol:$('aSymbol').value,options:$('aOptions').value.split('\n').map(x=>x.trim()).filter(Boolean),answer:Number($('aAnswer').value),enabled:$('aEnabled').checked};if(!draft.title.trim()||!draft.question.trim())throw Error('Completa el nombre y la pregunta.');const next=state.activities.filter(x=>x.id!==editId);next.push(draft);state.activities=validateActivities(next);save();activityEditor(draft.id);$('aStatus').textContent='Actividad guardada. Puedes probarla desde el inicio.'}catch(e){$('aStatus').textContent=e.message==='Actividad inválida'?'Revisa las opciones y el número de respuesta correcta.':e.message}};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>activityEditor(state.activities[+b.dataset.edit].id));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const i=+b.dataset.delete;if(confirm('¿Eliminar «'+state.activities[i].title+'» de este dispositivo?')){state.activities.splice(i,1);save();activityEditor()}})}
$('home').onclick=home;home();
